-- =============================================================================
-- Migración: importación masiva de "Base de datos Perforaciones MEyRNR.xlsx"
--            a public.perforaciones_registradas
-- Fecha: 2026-08-27
--
-- Registros: 869 nuevos (incluye 3 filas partidas en 2 por tener
--            dos perforaciones P1/P2 en el mismo lugar).
--
-- id: el "Codigo Pozo" del Excel ES el id (embebido en el uuid).
--     Codigo Pozo 1   -> id 00000000-0000-0000-0000-000000000001
--     Codigo Pozo 861 -> id 00000000-0000-0000-0000-000000000861
--   Las filas sin "Codigo Pozo" entero y las P2/BIS toman ids 862..869.
--   El registro ya cargado por el formulario pasa a id
--     00000000-0000-0000-0000-000000000870.
--
-- La columna codigo_pozo SE ELIMINA (DROP COLUMN) al final. El único valor que
--   contenía (el del registro del formulario) se copia antes a
--   nro_autorizacion_registro. El "N° Autorización/Registro" del Excel (1309/001)
--   también va a esa columna nueva.
--
-- Columnas nuevas (todas text): nro_expediente, nro_disposicion, nro_autorizacion_registro, nro_asunto, fecha_inicio_explotacion_texto, paraje_barrio, colonia, lote, seccion, manzana, parcela, chacra, calle, camino, ruta, otros_datos_ubicacion, corresponde_amse, nombre_pozo, bomba_marca_potencia, cementacion, revestimiento, coord_x_y, datos_acuifero_cuenca, muestras, cantidad_muestras, ubicacion
--
-- departamento_id / municipio_id: se resuelven contra departamentos.codigo y
--   municipios.codigo_municipio. Las filas que no se pudieron resolver quedan con
--   ese campo en NULL (ver reporte aparte). El dato original queda en las columnas
--   de ubicación / observaciones, no se pierde.
--
-- SUPUESTO: la tabla usa latitud_gms / longitud_gms (según export actual). Si en
--   tu base son latitud_dms / longitud_dms, cambiá esos 2 nombres abajo.
--
-- CÓMO CORRERLA: pg_dump de resguardo antes. Ejecutar completo (va en BEGIN/COMMIT).
--
-- CÓMO DESHACERLA:
--   BEGIN;
--   -- 1º restaurar el id del registro del formulario
--   UPDATE public.perforaciones_registradas
--     SET id = 'b1d48bd7-17fb-4d3a-b098-0e8664488a7c'
--     WHERE id = '00000000-0000-0000-0000-000000000870';
--   -- 2º borrar todo lo importado
--   DELETE FROM public.perforaciones_registradas
--     WHERE id::text LIKE '00000000-0000-0000-0000-%';
--   -- 3º volver a crear la columna y restaurar su valor
--   ALTER TABLE public.perforaciones_registradas ADD COLUMN codigo_pozo text;
--   UPDATE public.perforaciones_registradas
--     SET codigo_pozo = nro_autorizacion_registro
--     WHERE id = 'b1d48bd7-17fb-4d3a-b098-0e8664488a7c';
--   ALTER TABLE public.perforaciones_registradas
--     DROP COLUMN IF EXISTS nro_expediente,
--     DROP COLUMN IF EXISTS nro_disposicion,
--     DROP COLUMN IF EXISTS nro_autorizacion_registro,
--     DROP COLUMN IF EXISTS nro_asunto,
--     DROP COLUMN IF EXISTS fecha_inicio_explotacion_texto,
--     DROP COLUMN IF EXISTS paraje_barrio,
--     DROP COLUMN IF EXISTS colonia,
--     DROP COLUMN IF EXISTS lote,
--     DROP COLUMN IF EXISTS seccion,
--     DROP COLUMN IF EXISTS manzana,
--     DROP COLUMN IF EXISTS parcela,
--     DROP COLUMN IF EXISTS chacra,
--     DROP COLUMN IF EXISTS calle,
--     DROP COLUMN IF EXISTS camino,
--     DROP COLUMN IF EXISTS ruta,
--     DROP COLUMN IF EXISTS otros_datos_ubicacion,
--     DROP COLUMN IF EXISTS corresponde_amse,
--     DROP COLUMN IF EXISTS nombre_pozo,
--     DROP COLUMN IF EXISTS bomba_marca_potencia,
--     DROP COLUMN IF EXISTS cementacion,
--     DROP COLUMN IF EXISTS revestimiento,
--     DROP COLUMN IF EXISTS coord_x_y,
--     DROP COLUMN IF EXISTS datos_acuifero_cuenca,
--     DROP COLUMN IF EXISTS muestras,
--     DROP COLUMN IF EXISTS cantidad_muestras,
--     DROP COLUMN IF EXISTS ubicacion;
--   COMMIT;
--   NOTIFY pgrst, 'reload schema';
-- =============================================================================

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. Columnas nuevas
-- ---------------------------------------------------------------------------
ALTER TABLE public.perforaciones_registradas
  ADD COLUMN IF NOT EXISTS nro_expediente text,
  ADD COLUMN IF NOT EXISTS nro_disposicion text,
  ADD COLUMN IF NOT EXISTS nro_autorizacion_registro text,
  ADD COLUMN IF NOT EXISTS nro_asunto text,
  ADD COLUMN IF NOT EXISTS fecha_inicio_explotacion_texto text,
  ADD COLUMN IF NOT EXISTS paraje_barrio text,
  ADD COLUMN IF NOT EXISTS colonia text,
  ADD COLUMN IF NOT EXISTS lote text,
  ADD COLUMN IF NOT EXISTS seccion text,
  ADD COLUMN IF NOT EXISTS manzana text,
  ADD COLUMN IF NOT EXISTS parcela text,
  ADD COLUMN IF NOT EXISTS chacra text,
  ADD COLUMN IF NOT EXISTS calle text,
  ADD COLUMN IF NOT EXISTS camino text,
  ADD COLUMN IF NOT EXISTS ruta text,
  ADD COLUMN IF NOT EXISTS otros_datos_ubicacion text,
  ADD COLUMN IF NOT EXISTS corresponde_amse text,
  ADD COLUMN IF NOT EXISTS nombre_pozo text,
  ADD COLUMN IF NOT EXISTS bomba_marca_potencia text,
  ADD COLUMN IF NOT EXISTS cementacion text,
  ADD COLUMN IF NOT EXISTS revestimiento text,
  ADD COLUMN IF NOT EXISTS coord_x_y text,
  ADD COLUMN IF NOT EXISTS datos_acuifero_cuenca text,
  ADD COLUMN IF NOT EXISTS muestras text,
  ADD COLUMN IF NOT EXISTS cantidad_muestras text,
  ADD COLUMN IF NOT EXISTS ubicacion text;

-- ---------------------------------------------------------------------------
-- 2. Staging temporal con los datos crudos del Excel
-- ---------------------------------------------------------------------------
CREATE TEMP TABLE _stg_perf (
  id uuid,
  created_at timestamptz,
  fecha_mesa_entrada date,
  titular_representante text,
  documento_cuil text,
  uso_agua text,
  empresa_perforista text,
  caudal_m3h text,
  medicion_cte_caudal_m3h text,
  profundidad_perforacion_m text,
  profundidad_succion_m text,
  profundidad_nivel_estatico_m text,
  profundidad_nivel_dinamico_m text,
  diametro_perforacion text,
  observaciones text,
  latitud_decimal double precision,
  longitud_decimal double precision,
  latitud_gms text,
  longitud_gms text,
  departamento_code integer,
  municipio_code integer,
  nro_expediente text,
  nro_disposicion text,
  nro_autorizacion_registro text,
  nro_asunto text,
  fecha_inicio_explotacion_texto text,
  paraje_barrio text,
  colonia text,
  lote text,
  seccion text,
  manzana text,
  parcela text,
  chacra text,
  calle text,
  camino text,
  ruta text,
  otros_datos_ubicacion text,
  corresponde_amse text,
  nombre_pozo text,
  bomba_marca_potencia text,
  cementacion text,
  revestimiento text,
  coord_x_y text,
  datos_acuifero_cuenca text,
  muestras text,
  cantidad_muestras text,
  ubicacion text,
  geom_lon double precision,
  geom_lat double precision
) ON COMMIT DROP;


-- ---------------------------------------------------------------------------
-- 3. Insert final resolviendo FKs por código
-- ---------------------------------------------------------------------------
  id, created_at, updated_at, activo, fecha_mesa_entrada, titular_representante, documento_cuil,
  uso_agua, empresa_perforista, caudal_m3h, medicion_cte_caudal_m3h,
  profundidad_perforacion_m, profundidad_succion_m, profundidad_nivel_estatico_m,
  profundidad_nivel_dinamico_m, diametro_perforacion, observaciones,
  latitud_decimal, longitud_decimal, latitud_gms, longitud_gms,
  departamento_id, municipio_id, geom,
  nro_expediente,
  nro_disposicion,
  nro_autorizacion_registro,
  nro_asunto,
  fecha_inicio_explotacion_texto,
  paraje_barrio,
  colonia,
  lote,
  seccion,
  manzana,
  parcela,
  chacra,
  calle,
  camino,
  ruta,
  otros_datos_ubicacion,
  corresponde_amse,
  nombre_pozo,
  bomba_marca_potencia,
  cementacion,
  revestimiento,
  coord_x_y,
  datos_acuifero_cuenca,
  muestras,
  cantidad_muestras,
  ubicacion
)
SELECT
  s.id, s.created_at, s.created_at, true, s.fecha_mesa_entrada, s.titular_representante, s.documento_cuil,
  s.uso_agua, s.empresa_perforista, s.caudal_m3h, s.medicion_cte_caudal_m3h,
  s.profundidad_perforacion_m, s.profundidad_succion_m, s.profundidad_nivel_estatico_m,
  s.profundidad_nivel_dinamico_m, s.diametro_perforacion, s.observaciones,
  s.latitud_decimal, s.longitud_decimal, s.latitud_gms, s.longitud_gms,
  COALESCE(d.id, m.departamento_id), m.id,
  CASE WHEN s.geom_lon IS NOT NULL AND s.geom_lat IS NOT NULL
       THEN ST_SetSRID(ST_MakePoint(s.geom_lon, s.geom_lat), 4326) END,
  s.nro_expediente,
  s.nro_disposicion,
  s.nro_autorizacion_registro,
  s.nro_asunto,
  s.fecha_inicio_explotacion_texto,
  s.paraje_barrio,
  s.colonia,
  s.lote,
  s.seccion,
  s.manzana,
  s.parcela,
  s.chacra,
  s.calle,
  s.camino,
  s.ruta,
  s.otros_datos_ubicacion,
  s.corresponde_amse,
  s.nombre_pozo,
  s.bomba_marca_potencia,
  s.cementacion,
  s.revestimiento,
  s.coord_x_y,
  s.datos_acuifero_cuenca,
  s.muestras,
  s.cantidad_muestras,
  s.ubicacion
FROM _stg_perf s
LEFT JOIN public.departamentos d ON d.codigo = s.departamento_code
LEFT JOIN public.municipios   m ON m.codigo_municipio = s.municipio_code;

-- ---------------------------------------------------------------------------
-- 4. El registro ya cargado por el formulario -> último id
-- ---------------------------------------------------------------------------
UPDATE public.perforaciones_registradas
SET id = '00000000-0000-0000-0000-000000000870'
WHERE id = 'b1d48bd7-17fb-4d3a-b098-0e8664488a7c';

-- ---------------------------------------------------------------------------
-- 5. Se elimina la columna codigo_pozo (el "Codigo Pozo" ahora es el id).
--    Antes se guarda el único valor que tenía (el del registro del formulario)
--    en nro_autorizacion_registro para no perderlo.
-- ---------------------------------------------------------------------------
UPDATE public.perforaciones_registradas
SET nro_autorizacion_registro = codigo_pozo
WHERE codigo_pozo IS NOT NULL
  AND nro_autorizacion_registro IS NULL;

ALTER TABLE public.perforaciones_registradas DROP COLUMN codigo_pozo;

COMMIT;

NOTIFY pgrst, 'reload schema';

